(function(){'use strict';
/* Diagnostic Tools Database generator — jahdb-diagnostic-tools-generator-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed always makes the same record.
   src:"public" = Fact-checked public information */
function pad(n){var s=String(n);while(s.length<6)s='0'+s;return s;}
var PREFIX='JAH-DIAGTOOLS-';
var SRC='public';
var RECORD_KIND='diagnostic tool record';
var ANGLES=['overview','detailed','examples','faq','history','applications'];
var TOPICS=[{"title":"Multimeters","brief":"Multimeters measure voltage, current, and resistance — the essential electrical diagnostic tool.","points":["Measure DC/AC voltage, current, resistance, and continuity with one device.","Auto-ranging simplifies use; manual ranging teaches the skill.","Safety ratings (CAT II/III/IV) match the meter to the energy level — never exceed them.","True-RMS meters read non-sinusoidal waveforms accurately."],"examples":["Tracing a dead outlet to a tripped GFCI with voltage checks.","Finding a parasitic battery drain by measuring current draw."],"history":["The Avometer (1923) was the first multimeter.","Digital multimeters (1970s, Fluke) replaced analog movements."],"uses":["Electrical troubleshooting everywhere.","Automotive and HVAC diagnostics.","Electronics repair and hobby."],"qa":[["What should a beginner buy?","A CAT III 600V auto-ranging meter from a reputable brand — $30-50."],["Why is my reading wrong?","Check leads, range, mode (AC/DC), and that you're measuring the right points."],["Are cheap meters dangerous?","On mains power, yes — uncertified meters can explode. Buy rated."]]},{"title":"Oscilloscopes","brief":"Oscilloscopes display voltage over time, revealing waveforms invisible to multimeters.","points":["Bandwidth must exceed your signal's fastest edge — 100MHz covers most work.","Probes matter: 10x probes reduce loading; ground leads must be short.","Triggering stabilizes repeating waveforms for inspection.","Decode options read serial protocols (I2C, SPI, UART) directly."],"examples":["Spotting noise on a power rail causing random resets.","Verifying a sensor's pulse train timing."],"history":["CRT scopes (1940s-90s); digital storage scopes (1980s+) revolutionized capture.","USB and handheld scopes made them affordable."],"uses":["Electronics design and repair.","Automotive sensor diagnostics.","Power supply troubleshooting."],"qa":[["Do I need a scope as a hobbyist?","For digital/mixed-signal work, eventually yes — a used 100MHz scope suffices."],["What bandwidth?","5x your fastest signal; 100MHz handles most embedded work."],["Why is my waveform noisy?","Long ground leads pick up noise — use short ground springs."]]},{"title":"Logic Analyzers","brief":"Logic analyzers capture digital signals across many channels, decoding protocols and timing relationships.","points":["Channel counts from 8 to 100+; sample rate must exceed signal speed.","Protocol decoders translate raw bits into I2C/SPI/UART transactions.","Timing vs state modes trade resolution against depth.","Triggering on protocol events catches intermittent bugs."],"examples":["Capturing why an I2C sensor NACKs every 100th transaction.","Verifying SPI timing meets a datasheet's setup/hold."],"history":["HP led logic analysis in the 1970s-80s.","USB analyzers (Saleae, 2000s) democratized the tool."],"uses":["Embedded systems debugging.","Reverse-engineering protocols.","FPGA and digital design verification."],"qa":[["Scope or logic analyzer?","Scope for analog detail; logic analyzer for many-channel digital protocol work."],["How many channels?","At least 2x your bus width — 8-16 covers most embedded."],["Can software replace it?","For slow protocols, sometimes; hardware analyzers don't disturb timing."]]},{"title":"OBD-II Scanners","brief":"OBD-II scanners read a car's computer: trouble codes, live data, and readiness monitors.","points":["Codes (P0xxx) point to systems, not parts — diagnosis still required.","Live data (fuel trims, O2 sensors) reveals what the computer sees.","Freeze-frame captures conditions when the code set.","Bluetooth adapters plus phone apps make scanning cheap."],"examples":["A P0171 lean code traced via fuel trims to a vacuum leak, not the O2 sensor.","Checking readiness monitors before an emissions test."],"history":["OBD-II became mandatory in the US for 1996 model years.","CAN bus (2008+) standardized communications."],"uses":["DIY car diagnostics.","Pre-purchase inspections.","Monitoring repairs' effectiveness."],"qa":[["Will a scanner tell me what's broken?","It tells you symptoms; interpretation and testing find the cause."],["Can I clear codes?","Yes, but they'll return if the fault persists — fix, then clear."],["Cheap vs professional scanners?","Cheap reads codes; pro tools add bi-directional control and deep data."]]},{"title":"Thermal Imaging Cameras","brief":"Thermal cameras see heat: finding insulation gaps, electrical hotspots, and water leaks invisibly.","points":["Resolution (pixels) determines detail; sensitivity (mK) determines subtlety.","Electrical: hot breakers and connections reveal overloads before failure.","Building: missing insulation and air leaks glow in thermal.","Emissivity affects readings — shiny metals read wrong without adjustment."],"examples":["A hot breaker pinpointed before it failed.","Missing wall insulation revealed as cold stripes."],"history":["Military origins; FLIR commercialized handhelds (2000s).","Phone attachments (2010s) made thermal affordable."],"uses":["Electrical preventive maintenance.","Building energy audits.","Plumbing leak detection."],"qa":[["How much should I spend?","$200-400 phone attachments suffice for home use; pros need higher resolution."],["Can they see through walls?","No — they see surface temperatures; patterns suggest what's behind."],["Are they hard to interpret?","Somewhat — training helps distinguish real issues from reflections."]]},{"title":"Borescopes and Inspection Cameras","brief":"Borescopes snake cameras into engines, walls, and pipes — seeing without disassembly.","points":["Articulating tips look around corners; rigid borescopes suit straight paths.","Engine inspection: cylinder walls, valves, and carbon buildup.","Wall and pipe inspection without destructive opening.","Record photos/video to document findings."],"examples":["Scoping cylinders to find scored walls before buying a used car.","Locating a pipe blockage without opening walls."],"history":["Medical endoscopes inspired industrial borescopes.","Cheap USB/articulating models (2010s) democratized them."],"uses":["Engine diagnostics.","Plumbing and HVAC inspection.","Home inspection."],"qa":[["What length do I need?","Match your deepest inspection — 3-5m covers most automotive/home."],["Are phone borescopes good?","Surprisingly yes for the price — fine for occasional use."],["Can I inspect my own engine?","Through spark-plug holes, yes — it's a great pre-purchase check."]]},{"title":"Battery Testers","brief":"Battery testers assess health beyond voltage: conductance, load, and cold-cranking amps.","points":["Voltage alone lies — a battery can show 12.6V and still fail under load.","Conductance testers estimate CCA without heavy load testing.","Load testers apply real current for definitive results.","Test both battery and charging system — alternators kill good batteries."],"examples":["A conductance test condemning a battery before winter.","Finding a weak alternator behind repeated dead batteries."],"history":["Carbon-pile load testers (mid-20th c.); conductance testers (1990s+).","Start-stop and AGM batteries raised testing stakes."],"uses":["Preventing no-start surprises.","Warranty testing.","Fleet maintenance."],"qa":[["Why did my battery die suddenly?","Often a weak cell masked by mild weather — test before winter."],["Can I test at home?","Yes — $30-50 conductance testers work well."],["Battery or alternator?","Test both: charge the battery, then check charging voltage running."]]},{"title":"Network Cable Testers","brief":"Cable testers verify wiring: continuity, pairing, length, and faults in Ethernet and coax runs.","points":["Basic testers check continuity and pairing — catching miswires.","TDR (time-domain reflectometry) locates breaks by distance.","Certifiers verify Cat6/6A performance to standard.","Tone generators and probes trace cables through walls."],"examples":["Finding a split pair causing intermittent gigabit drops.","Locating a break 40m down a buried run."],"history":["Simple continuity testers (1980s); certifiers followed structured-cabling standards.","PoE testing became essential as devices drew power over Ethernet."],"uses":["Network installations.","Troubleshooting intermittent connections.","Verifying contractor work."],"qa":[["Why is my gigabit link at 100Mbps?","Often a bad pair — cable testers find it in minutes."],["Do I need a certifier?","For contracted installs, yes; for home, a qualifier suffices."],["Can I test PoE?","Yes — PoE testers verify power delivery per pair."]]},{"title":"Clamp Meters","brief":"Clamp meters measure current without breaking the circuit — clamping around a conductor.","points":["AC clamp uses transformer action; DC clamp needs Hall sensors.","Measure current on live circuits safely — no series connection.","Inrush mode captures motor starting current.","Some add full multimeter functions for one-tool convenience."],"examples":["Measuring a motor's running current without shutting down.","Finding which circuit draws power in a panel."],"history":["Clamp-on ammeters (early 20th c.); Hall-effect DC clamps later.","Modern clamps rival multimeters in features."],"uses":["Electrical maintenance.","HVAC current checks.","Solar and automotive DC systems."],"qa":[["AC or DC clamp?","AC-only is cheaper; DC-capable costs more but covers solar/auto."],["Why zero the DC clamp?","Hall sensors drift — zero with jaws closed before measuring."],["Can I clamp both wires?","No — clamp one conductor; both cancels the field."]]},{"title":"Pressure Testers and Gauges","brief":"Pressure diagnostics verify fuel, oil, compression, cooling, and HVAC pressures against spec.","points":["Compression testers reveal engine mechanical health per cylinder.","Fuel pressure gauges diagnose pump and regulator issues.","Cooling-system testers pressurize to find leaks.","Manifold gauges service AC/refrigeration systems."],"examples":["A compression test finding one dead cylinder explaining a misfire.","Pressurizing a cooling system to find a hidden leak."],"history":["Mechanical gauges (19th c.) → digital gauges with data logging.","OBD live data supplements but doesn't replace physical gauges."],"uses":["Engine mechanical diagnosis.","Fuel system troubleshooting.","HVAC service."],"qa":[["What compression is good?","Varies by engine; consistency across cylinders matters most."],["Wet vs dry compression test?","Wet (oil added) distinguishing rings from valves."],["Can I do this myself?","Yes — testers are affordable and procedures straightforward."]]},{"title":"Medical Thermometers","brief":"Thermometers measure body temperature — the simplest vital sign and a frontline diagnostic.","points":["Types: digital oral, infrared forehead/ear, and traditional (now rare).","Fever thresholds vary by site; know your device's reference.","Infrared is fast and non-contact — ideal for kids and screening.","Trends matter more than single readings."],"examples":["An infrared thermometer screening quickly during flu season.","Tracking fever response to medication over days."],"history":["Galileo's thermoscope (1590s); medical thermometers (1860s, Wunderlich).","Digital and infrared replaced mercury by the 2000s."],"uses":["Fever detection at home.","Screening in clinics and workplaces.","Monitoring illness progression."],"qa":[["What counts as fever?","Generally 100.4°F/38°C+ orally — but know your baseline."],["Forehead or oral?","Oral is more accurate; forehead is faster for screening."],["Can I trust cheap infrared?","For screening yes; confirm borderline readings with oral."]]},{"title":"Blood Pressure Monitors","brief":"Home BP monitors track hypertension — the silent condition behind heart disease and stroke.","points":["Upper-arm cuffs are more accurate than wrist models.","Proper technique: seated, back supported, cuff at heart level, rested 5 minutes.","Track trends over weeks, not single readings.","Validated monitors (clinically tested) are worth seeking."],"examples":["Home readings revealing white-coat hypertension.","Medication adjustments guided by weeks of home data."],"history":["Riva-Rocci's cuff (1896); home electronic monitors (1980s+).","Connected monitors now share data with doctors."],"uses":["Hypertension management.","Medication effectiveness tracking.","Early detection."],"qa":[["What numbers are normal?","Generally under 120/80; your doctor sets your targets."],["Why do readings vary?","Activity, caffeine, stress, and technique all shift readings."],["Wrist or arm?","Arm — wrist models are position-sensitive."]]},{"title":"Pulse Oximeters","brief":"Pulse oximeters clip on a finger to measure blood oxygen saturation and heart rate non-invasively.","points":["SpO2 (oxygen saturation) and pulse rate from light absorption.","Normal SpO2 is 95-100%; below 90% warrants medical attention.","Cold fingers, nail polish, and motion cause false lows.","Home monitoring became mainstream during respiratory illness waves."],"examples":["Monitoring recovery at home during respiratory illness.","Athletes tracking altitude acclimatization."],"history":["Invented 1970s (Nihon Kohden); fingertip models (2000s) democratized.","Smartwatches added wrist SpO2 (2010s)."],"uses":["Respiratory illness monitoring.","Sleep apnea screening hints.","Altitude and fitness."],"qa":[["When should I worry?","Consistently below 92-94% or dropping trends — call your doctor."],["Are phone apps accurate?","No — they lack the proper sensors; use a real oximeter."],["Why does it read low?","Cold hands, polish, or movement — warm up and retry."]]},{"title":"Glucometers","brief":"Glucometers measure blood sugar from a fingerstick — essential diabetes management.","points":["Test strips, lancets, and meters form the system; strip costs dominate.","CGMs (continuous monitors) now complement fingersticks with trends.","Timing matters: fasting, pre/post-meal readings tell different stories.","Log results — patterns guide medication and diet."],"examples":["A post-meal reading revealing which foods spike glucose.","CGM trends preventing nighttime lows."],"history":["Home glucose meters (1980s) transformed diabetes care.","CGMs (2000s-2010s) added continuous insight."],"uses":["Diabetes daily management.","Medication tuning with doctors.","Diet feedback."],"qa":[["Fingerstick or CGM?","CGM for insight; fingersticks for calibration and backup."],["Are cheap meters accurate?","Regulated accuracy standards apply; technique matters most."],["What affects readings?","Food residue on fingers, strip age, temperature, hematocrit."]]},{"title":"Stethoscopes","brief":"The stethoscope amplifies body sounds — heart, lungs, bowels — the clinician's iconic tool.","points":["Diaphragm for high frequencies (lung sounds); bell for low (heart murmurs).","Technique and anatomy knowledge matter more than price.","Electronic stethoscopes amplify and record for teaching.","Still irreplaceable for blood-pressure measurement by auscultation."],"examples":["Detecting a heart murmur warranting echocardiography.","Assessing breath sounds in pneumonia."],"history":["Laennec invented it (1816); binaural models followed.","Electronic versions (2000s) added amplification."],"uses":["Physical examinations.","Blood pressure measurement.","Teaching auscultation."],"qa":[["Do I need an expensive one?","Mid-range suffices for most; technique dominates."],["Can patients use them?","With guidance, for basic monitoring — interpretation needs training."],["Are electronic better?","For hearing-impaired clinicians and teaching, yes."]]},{"title":"ECG Machines","brief":"ECG machines record the heart's electrical activity — diagnosing arrhythmias, ischemia, and more.","points":["12-lead ECG is the clinical standard; placement matters enormously.","Rhythm strips reveal arrhythmias; 12-leads localize ischemia.","Portable and wearable ECGs extend monitoring beyond clinics.","Interpretation requires training — machines flag, clinicians decide."],"examples":["An ECG catching atrial fibrillation in a routine check.","ST elevation triggering emergency cardiac catheterization."],"history":["Einthoven's string galvanometer (1903) won a Nobel.","Portable ECGs (mid-20th c.); wearables (2010s)."],"uses":["Chest pain evaluation.","Arrhythmia diagnosis.","Pre-surgical screening."],"qa":[["Can smartwatches replace ECGs?","Single-lead watches screen for AFib; 12-lead diagnosis needs clinical ECG."],["What does the ECG show?","Electrical timing — rhythm, conduction, and ischemia patterns."],["Is it painful?","No — stickers and wires, completely non-invasive."]]},{"title":"Ultrasound Machines","brief":"Ultrasound images the body with sound waves — safe, real-time, and radiation-free.","points":["No ionizing radiation — safe in pregnancy.","Real-time imaging guides procedures (IVs, biopsies).","Doppler modes visualize blood flow.","Operator skill hugely affects quality."],"examples":["Prenatal scans monitoring fetal development.","Guiding a difficult IV placement in real time."],"history":["Medical ultrasound (1950s-60s); Doppler and 3D followed.","Handheld probes (2010s) brought it to bedside."],"uses":["Pregnancy monitoring.","Cardiac and abdominal imaging.","Procedure guidance."],"qa":[["Is ultrasound safe?","Decades of use show no ionizing risk; used judiciously."],["Why gel?","Air blocks sound waves — gel couples the probe to skin."],["Can it see everything?","No — bone and air block it; CT/MRI cover those gaps."]]},{"title":"X-Ray Systems","brief":"X-rays image dense structures — bones, chest, teeth — with ionizing radiation used carefully.","points":["Bone fractures and joint assessment are the classic uses.","Chest X-rays screen lungs and heart size.","Dental X-rays find decay invisible to the eye.","Dose is low but cumulative — imaging must be justified."],"examples":["An X-ray revealing a hairline fracture missed on exam.","Dental X-rays catching decay between teeth early."],"history":["Röntgen discovered X-rays (1895); medical use was immediate.","Digital radiography (2000s) replaced film."],"uses":["Fracture diagnosis.","Chest and dental screening.","Guiding orthopedic procedures."],"qa":[["Are X-rays dangerous?","Doses are tiny; benefits vastly outweigh risk when justified."],["Why the lead apron?","Shielding for sensitive tissues, especially in pregnancy."],["X-ray vs CT?","X-ray is 2D and low-dose; CT is 3D and higher-dose."]]},{"title":"MRI Scanners","brief":"MRI uses magnets and radio waves for exquisite soft-tissue detail — no radiation.","points":["Superior soft-tissue contrast: brain, spine, joints, tumors.","No ionizing radiation — safe for repeated imaging.","Loud, slow, and confining — claustrophobia and implants are issues.","Functional MRI maps brain activity."],"examples":["An MRI revealing a herniated disc explaining leg pain.","Brain MRI localizing a stroke within hours."],"history":["Lauterbur and Mansfield's work (1970s) won the 2003 Nobel.","Clinical MRI spread through the 1980s-90s."],"uses":["Neurological diagnosis.","Sports medicine and orthopedics.","Cancer staging."],"qa":[["Is MRI safe?","No radiation; the magnet is the hazard — no metal implants."],["Why so loud?","Rapidly switching gradient coils — ear protection provided."],["MRI vs CT?","MRI for soft tissue detail; CT for speed, bone, and emergencies."]]},{"title":"CT Scanners","brief":"CT combines X-rays with computing for cross-sectional 3D images — fast and detailed.","points":["Speed makes CT the trauma and stroke workhorse.","3D reconstructions guide surgery precisely.","Higher radiation dose than plain X-ray — used judiciously.","Contrast dye enhances vessels and organs."],"examples":["A trauma CT finding internal bleeding in minutes.","Stroke CT distinguishing clot from bleed to guide treatment."],"history":["Hounsfield and Cormack's invention (1970s) won the 1979 Nobel.","Multi-slice CT (2000s) made scans seconds-fast."],"uses":["Emergency diagnosis.","Cancer detection and staging.","Surgical planning."],"qa":[["How much radiation?","Roughly 100x a chest X-ray; justified by diagnostic value."],["Is contrast safe?","Generally; kidney function is checked first."],["CT vs MRI?","CT is fast and bone-friendly; MRI is detailed for soft tissue."]]},{"title":"Blood Lab Analyzers","brief":"Automated analyzers run blood panels: CBC, chemistry, and more — the backbone of medical diagnosis.","points":["CBC counts red/white cells and platelets — infection, anemia, clotting clues.","Chemistry panels check electrolytes, kidney, and liver function.","Point-of-care devices bring basic panels to clinics in minutes.","Reference ranges vary by lab; trends beat single values."],"examples":["A CBC revealing anemia explaining fatigue.","Electrolytes guiding emergency treatment."],"history":["Automated cell counters (1950s-60s, Coulter) revolutionized hematology.","Point-of-care testing expanded access (2000s+)."],"uses":["Routine health screening.","Disease diagnosis and monitoring.","Pre-surgical assessment."],"qa":[["Fasting or not?","Glucose and lipids usually need fasting — follow instructions."],["Why do results vary?","Hydration, time of day, and lab methods all shift values."],["Can I interpret my own labs?","Trends and flags help; diagnosis needs your clinician."]]},{"title":"Rapid Test Kits","brief":"Rapid tests deliver answers in minutes at home or bedside: infections, pregnancy, drugs, and more.","points":["Lateral-flow technology (like pregnancy tests) dominates.","Sensitivity vs specificity: know what false negatives/positives mean.","Follow instructions exactly — timing and sample matter.","Confirm critical results with lab testing."],"examples":["A rapid strep test guiding same-visit treatment.","Home COVID tests enabling quick decisions."],"history":["Home pregnancy tests (1970s-80s) pioneered the format.","The pandemic normalized rapid infectious-disease testing."],"uses":["Fast triage decisions.","Home health monitoring.","Workplace and travel screening."],"qa":[["Are rapid tests accurate?","Good but imperfect — understand sensitivity for your use."],["Negative but symptomatic?","Retest or get lab confirmation — false negatives happen."],["How do I read faint lines?","Any line in time is positive; read at the specified time only."]]},{"title":"Compression Testers (Engine)","brief":"Compression testers measure each cylinder's ability to hold pressure — revealing engine mechanical health.","points":["Low compression on one cylinder suggests valves or rings.","Wet tests (oil added) distinguish ring wear from valve issues.","Consistency across cylinders matters more than absolute numbers.","Leak-down testers pinpoint exactly where compression escapes."],"examples":["A wet test proving worn rings versus bad valves.","Pre-purchase testing revealing a tired engine."],"history":["Mechanical gauges served for a century; digital added recording.","Leak-down testing refined diagnosis."],"uses":["Misfire diagnosis.","Pre-purchase inspections.","Rebuild decisions."],"qa":[["What numbers are good?","Varies; within 10-15% across cylinders is the rule."],["Can I do it myself?","Yes — basic tools and 30 minutes."],["Compression vs leak-down?","Compression is quick screening; leak-down pinpoints."]]},{"title":"Refrigerant Leak Detectors","brief":"Leak detectors find AC/refrigeration refrigerant escapes: electronic sniffers, UV dye, and bubbles.","points":["Electronic sniffers detect halogen refrigerants at tiny concentrations.","UV dye injected into systems reveals leaks under blacklight.","Nitrogen pressure testing finds leaks without refrigerant.","Fix leaks — topping off without repair wastes money and harms the environment."],"examples":["A sniffer finding a pinhole evaporator leak.","UV dye glowing at a compressor seal."],"history":["Halide torches (early) → electronic sniffers (modern).","Environmental rules made leak repair mandatory."],"uses":["AC performance diagnosis.","Environmental compliance.","Preventing compressor damage from low charge."],"qa":[["Can I just add refrigerant?","It'll leak out again — find and fix the leak."],["Which method is best?","Electronic for speed, UV for confirmation, nitrogen for empty systems."],["Is DIY legal?","Regulations vary; certified handling is required in many places."]]},{"title":"Insulation Testers (Megohmmeters)","brief":"Megohmmeters apply high voltage to verify insulation integrity — preventing shock and fire.","points":["Test motor windings, cables, and transformers for insulation breakdown.","PI (polarization index) trending predicts failures.","De-energize and discharge before testing — the tester itself is hazardous.","Low readings mean moisture, contamination, or damaged insulation."],"examples":["A motor rewound before it failed catastrophically.","Cable insulation testing before energizing new installs."],"history":["Hand-cranked meggers (early 20th c.); electronic models followed.","Predictive maintenance programs made them standard."],"uses":["Motor maintenance.","Cable commissioning.","Preventing electrical fires."],"qa":[["What reading is good?","Varies by equipment; trending over time matters most."],["Is it dangerous?","The test voltage is — follow safety procedures strictly."],["How often test?","Per maintenance schedules; critical motors more often."]]},{"title":"Vibration Analyzers","brief":"Vibration analysis detects rotating-equipment faults — bearings, imbalance, misalignment — before failure.","points":["FFT spectra reveal fault frequencies characteristic of each defect.","Trending over time predicts failures months ahead.","Route-based collection covers plant equipment systematically.","ISO standards define severity zones."],"examples":["A bearing defect caught months before seizure.","Misalignment corrected before it destroyed seals."],"history":["Portable analyzers (1980s) brought it to plants.","Wireless sensors (2010s) enabled continuous monitoring."],"uses":["Predictive maintenance.","Preventing unplanned downtime.","Commissioning new equipment."],"qa":[["What faults can it find?","Bearings, imbalance, misalignment, looseness, gear issues."],["Do I need training?","Yes — interpretation is a real skill."],["Wireless vs route-based?","Wireless for critical assets; routes for the rest."]]},{"title":"Ultrasonic Thickness Gauges","brief":"UT gauges measure material thickness from one side — finding corrosion without cutting.","points":["Sound waves time their round trip through the material.","Corrosion monitoring on pipes, tanks, and structures.","Single-side access suffices — no need to reach both sides.","Calibration on known thickness ensures accuracy."],"examples":["Pipeline corrosion mapped without shutdown.","Tank floor thinning found before leaks."],"history":["Sonar principles adapted for NDT (mid-20th c.).","Digital gauges made it routine."],"uses":["Corrosion monitoring.","Quality control in manufacturing.","Safety inspections."],"qa":[["How accurate?","Typically ±0.1mm with proper calibration."],["What materials?","Metals, plastics, glass — anything that conducts sound well."],["Do I need couplant?","Yes — gel couples the probe to the surface."]]},{"title":"Moisture Meters","brief":"Moisture meters find water in buildings: pin-type and pinless, for leak and mold prevention.","points":["Pin meters measure between probes — precise but leave holes.","Pinless scan large areas non-destructively.","Map moisture to find leak sources, not just symptoms.","Establish dry standards — readings are relative."],"examples":["Tracing a ceiling stain to a roof leak, not plumbing.","Verifying framing is dry before closing walls."],"history":["Wood-industry origins; building diagnostics adopted them.","Pinless technology sped surveys."],"uses":["Leak detection.","Mold prevention.","Pre-purchase home inspection."],"qa":[["Pin or pinless?","Pinless for scanning, pin for precise verification."],["What reading is wet?","Compare to known-dry areas of the same material."],["Can they find mold?","They find moisture that enables mold — inspect visually too."]]},{"title":"pH Meters and Water Test Kits","brief":"pH and water testing protect health and equipment: pools, aquariums, wells, and drinking water.","points":["pH meters need calibration with buffer solutions.","Test strips are quick; liquid kits and meters are more accurate.","Well owners should test annually for bacteria, nitrates, and metals.","Pool chemistry: pH, chlorine, and alkalinity in balance."],"examples":["A pool's cloudy water fixed by balancing pH and chlorine.","Well testing revealing nitrate contamination."],"history":["Litmus is ancient; glass electrodes (1900s) enabled meters.","Home kits democratized testing."],"uses":["Drinking water safety.","Pool and aquarium health.","Agriculture and brewing."],"qa":[["Strips or meter?","Strips for quick checks; meters for precision."],["How often calibrate pH meters?","Before each critical use; store probes wet."],["What's in a good well test?","Bacteria, nitrates, pH, and local concerns (arsenic, radon)."]]},{"title":"Sound Level Meters","brief":"Sound level meters quantify noise: workplace safety, environmental compliance, and audio work.","points":["dB(A) weighting matches human hearing for safety measurements.","OSHA/NIOSH limits define allowable exposures.","Calibrators ensure accuracy before critical measurements.","Logging meters document exposure over shifts."],"examples":["A workplace survey identifying hearing-protection zones.","Documenting neighborhood noise for a complaint."],"history":["Standardized meters (mid-20th c.); digital logging followed.","Phone apps approximate but don't replace calibrated meters."],"uses":["Hearing conservation programs.","Environmental noise compliance.","Audio system setup."],"qa":[["Are phone apps accurate?","Ballpark only — microphones aren't calibrated."],["What level is dangerous?","85 dB(A) over 8 hours is the common action level."],["How do I measure properly?","Calibrate, use A-weighting and slow response for safety work."]]},{"title":"Light Meters","brief":"Light meters measure illumination: photography exposure, workplace lighting, and grow operations.","points":["Photography: incident meters read light falling on subjects — more accurate than reflective.","Workplace: lux levels verify code compliance.","Grow lights: PAR meters measure plant-usable light.","Smartphone apps approximate; dedicated meters are accurate."],"examples":["A photographer nailing exposure with an incident reading.","Verifying office lighting meets standards."],"history":["Selenium meters (1930s); silicon and digital followed.","Specialized PAR meters serve horticulture."],"uses":["Photography and cinematography.","Workplace safety compliance.","Horticulture lighting."],"qa":[["Incident or reflective?","Incident for accuracy; reflective (in-camera) for convenience."],["What lux for offices?","Typically 300-500 lux for general office work."],["Do I need one with digital cameras?","In-camera meters suffice mostly; incident meters help with flash and tricky light."]]},{"title":"Tachometers","brief":"Tachometers measure rotational speed — RPM — for engines, motors, and machinery.","points":["Contact tachometers touch shafts; non-contact use lasers or strobes.","Engine diagnostics compare RPM to spec under load.","Stroboscopic tachometers freeze motion to read speed.","Many multimeters and scan tools include RPM functions."],"examples":["Verifying idle speed after a tune-up.","A strobe revealing a slipping belt."],"history":["Mechanical tachometers (19th c.); electronic and optical followed.","Laser tachometers made non-contact easy."],"uses":["Engine tuning.","Motor maintenance.","Machinery commissioning."],"qa":[["Why does RPM matter?","It reveals load, misfires, and governor operation."],["Contact or laser?","Laser for safety and convenience; contact for precision."],["What RPM should idle be?","Varies by engine — check specs, typically 600-900."]]},{"title":"Smoke Machines (Leak Detection)","brief":"Automotive smoke machines fill intake or EVAP systems with visible vapor, revealing leaks instantly.","points":["EVAP leaks (P0442 etc.) are found in minutes, not hours.","Intake leaks causing lean codes show as escaping smoke.","Low-pressure smoke is safe for delicate systems.","UV-enhanced smoke pinpoints exact locations."],"examples":["Finding a cracked EVAP hose behind a persistent code.","An intake gasket leak revealed as a smoke wisp."],"history":["Shop-built rigs preceded commercial machines (2000s).","EVAP regulations made them essential."],"uses":["EVAP system diagnosis.","Intake and vacuum leak hunting.","Turbocharger plumbing checks."],"qa":[["Can I DIY smoke?","Commercial machines are affordable; DIY rigs risk overpressure."],["Is the smoke safe?","Purpose-made fluid is safe for systems and technicians."],["What pressure?","Very low — EVAP systems tolerate ~0.5 psi."]]},{"title":"Fuel Pressure Testers","brief":"Fuel pressure gauges verify pump and regulator health against manufacturer specs.","points":["Low pressure causes lean conditions, hesitation, and no-starts.","Bleed-down tests reveal leaking injectors or check valves.","Spec varies widely — look up your vehicle's numbers.","Safety: relieve pressure before disconnecting; have fire precautions."],"examples":["A weak pump diagnosed by pressure dropping under load.","Bleed-down proving a leaking injector."],"history":["Mechanical gauges served for decades; digital added recording.","Returnless systems changed test procedures."],"uses":["No-start and hesitation diagnosis.","Pump and regulator verification.","Injector leak detection."],"qa":[["What pressure is normal?","Typically 35-65 psi port injection; direct injection runs thousands — check specs."],["Is it dangerous?","Fuel under pressure demands care — relieve pressure first."],["Gauge or scan tool?","Scan tools show commanded pressure; gauges show actual."]]},{"title":"Circuit Tracers","brief":"Circuit tracers identify breakers and trace wires through walls without guesswork.","points":["Transmitters inject signals; receivers follow them through walls.","Breaker finders match outlets to breakers in minutes.","Tone and probe kits trace data cables.","De-energize when possible; use rated tools when not."],"examples":["Finding the right breaker without the flip-and-shout routine.","Tracing a dead wire's path through walls."],"history":["Simple continuity tracers evolved into signal-injection tools.","Digital filtering improved accuracy in noisy panels."],"uses":["Electrical work preparation.","Renovation mapping.","Troubleshooting dead circuits."],"qa":[["Do they work on live circuits?","Many do, with proper ratings — de-energize when possible."],["How accurate?","Good enough to identify the right breaker or wire run."],["Worth buying for DIY?","Breaker finders pay for themselves in saved frustration."]]},{"title":"Radon Test Kits","brief":"Radon kits measure the radioactive gas that is the second leading cause of lung cancer.","points":["Short-term kits (days) screen; long-term (months) give definitive readings.","The action level is 4 pCi/L in the US.","Test lowest lived-in levels; mitigate with sub-slab systems.","Retest after mitigation and every few years."],"examples":["A home test revealing 8 pCi/L, fixed with a mitigation system.","Pre-purchase testing informing negotiations."],"history":["Radon risks recognized (1980s); testing became standard in real estate.","Continuous monitors added real-time insight."],"uses":["Homebuyer due diligence.","Lung cancer prevention.","Real estate transactions."],"qa":[["How dangerous is radon?","Second leading cause of lung cancer — but fixable."],["Short or long-term test?","Short-term to screen, long-term to decide."],["How is it fixed?","Sub-slab depressurization — effective and routine."]]},{"title":"Mold Test Kits","brief":"Mold kits sample air or surfaces for mold — though professional assessment usually matters more.","points":["Air cassettes and surface swabs are the common methods.","Outdoor baseline comparisons give context.","Kits identify presence; pros assess extent and cause.","Moisture control prevents mold better than any test."],"examples":["Post-leak testing confirming remediation worked.","A surface sample identifying the mold type."],"history":["Growing awareness (2000s) created the consumer kit market.","Professionals emphasize moisture assessment over spore counts."],"uses":["Post-water-damage verification.","Health concern investigations.","Real estate disclosure."],"qa":[["Do I need to test for mold?","If you see or smell it, fix moisture and clean — testing rarely changes the plan."],["Are home kits accurate?","They detect spores, but interpretation needs context."],["What's the real fix?","Find and fix moisture; clean or remove affected materials."]]},{"title":"Lead Test Kits","brief":"Lead kits detect the toxic metal in paint, water, and soil — critical for older homes.","points":["3M LeadCheck swabs are the EPA-recognized consumer standard for paint.","Water testing needs lab analysis for accuracy.","Pre-1978 homes are the primary concern.","Professional risk assessments guide remediation."],"examples":["Swab testing revealing lead paint before a renovation.","Water lab results prompting filter installation."],"history":["Lead's dangers known for centuries; US paint banned it in 1978.","Flint's crisis (2010s) renewed water-testing urgency."],"uses":["Renovation safety.","Child health protection.","Real estate due diligence."],"qa":[["Are swabs reliable?","LeadCheck swabs are good screeners; lab tests confirm."],["What if paint tests positive?","Don't disturb it — get professional guidance on encapsulation or abatement."],["Is my water safe?","Test through a certified lab, especially with old pipes."]]},{"title":"Home Inspection Tools","brief":"Home inspectors' toolkit: the instruments behind a thorough pre-purchase inspection.","points":["Moisture meters, infrared cameras, and electrical testers form the core.","Ladders, probes, and mirrors access attics and crawlspaces.","Drones inspect roofs safely.","Reporting software turns findings into actionable reports."],"examples":["Infrared revealing missing insulation a visual inspection missed.","A drone finding roof damage without ladder risk."],"history":["Home inspection professionalized (1970s-80s).","Technology (IR, drones) expanded what's inspectable."],"uses":["Pre-purchase due diligence.","Maintenance planning.","New-construction verification."],"qa":[["Should I attend the inspection?","Yes — you'll learn your house's systems firsthand."],["What can't inspectors see?","Inside walls, under slabs, and latent defects — inspections are visual plus tools."],["How do I choose an inspector?","Certification, sample reports, and reviews — not just price."]]},{"title":"Diagnostic Tool Care and Calibration","brief":"Keeping diagnostic tools accurate: calibration, maintenance, and proper use.","points":["Calibration verifies accuracy against standards — critical for safety tools.","Batteries and leads are the common failure points.","Store meters and scopes protected from drops and moisture.","Know each tool's limits — the wrong tool gives wrong answers confidently."],"examples":["Annual calibration keeping a torque wrench trustworthy.","Replacing worn test leads before they lie."],"history":["ISO 17025 governs calibration labs.","Right-to-repair debates affect tool serviceability."],"uses":["Trustworthy measurements.","Tool longevity.","Safety."],"qa":[["How often calibrate?","Per manufacturer and criticality — annually is typical for pro tools."],["Can I calibrate myself?","Field checks yes; certified calibration needs a lab."],["When replace vs repair?","When calibration fails repeatedly or repair exceeds replacement value."]]},{"title":"Power Quality Analyzers","brief":"Power quality analyzers diagnose electrical supply issues: sags, swells, harmonics, and transients.","points":["Voltage sags and swells damage sensitive equipment.","Harmonics from non-linear loads overheat neutrals and transformers.","Transients (spikes) reveal surge problems.","Logging over days catches intermittent issues."],"examples":["Harmonics traced to failing LED drivers overheating a neutral.","A sag log proving utility-side problems."],"history":["Analog meters gave way to digital power analyzers (1980s+).","Power electronics proliferation made PQ analysis essential."],"uses":["Industrial troubleshooting.","Data center power validation.","Utility dispute resolution."],"qa":[["What is power quality?","How cleanly power is delivered — voltage stability, harmonics, transients."],["Do I need one at home?","Rarely — a UPS with monitoring suffices for most homes."],["What causes harmonics?","Non-linear loads: VFDs, LED drivers, computer power supplies."]]},{"title":"Function Generators","brief":"Function generators produce test waveforms — sine, square, arbitrary — for circuit testing.","points":["Test amplifiers, filters, and digital circuits with known inputs.","Arbitrary waveform generators replay captured real-world signals.","Sweep and modulation test frequency response.","Pair with a scope to see input vs output."],"examples":["Sweeping a filter to plot its frequency response.","Replaying a captured sensor glitch to test firmware."],"history":["HP's 200A (1939) was an early audio oscillator.","DDS and arbitrary generators (1990s+) added precision."],"uses":["Electronics design and repair.","Audio equipment testing.","Education."],"qa":[["Do I need one?","For analog/filter work, yes; digital-only folks can often skip."],["What specs matter?","Frequency range, waveform types, and output amplitude."],["Can software generate signals?","Sound cards work for audio frequencies; dedicated generators go further."]]},{"title":"Automotive Scan Tool Live Data","brief":"Beyond codes, pro scan tools stream live sensor data and command actuators for active testing.","points":["Graph PIDs to spot glitches invisible in numbers.","Bi-directional controls command fans, injectors, and solenoids.","Mode 6 data reveals pending failures before codes set.","Record and review — intermittent faults need captured data."],"examples":["Commanding a cooling fan on to verify the circuit.","Mode 6 showing a misfire count climbing before the code."],"history":["OBD-II (1996) standardized basic data; manufacturer tools went deeper.","Affordable pro-level tools (2010s) democratized bi-directional control."],"uses":["Intermittent fault diagnosis.","Verifying repairs actively.","Pre-purchase deep inspection."],"qa":[["What's bi-directional control?","The scan tool commanding components — fans, windows, injectors — for testing."],["Is live data hard to read?","Start with 4-6 key PIDs; experience builds pattern recognition."],["Cheap dongle or pro tool?","Dongles read data; pro tools command and graph deeply."]]},{"title":"Torque Testers","brief":"Torque verification ensures fasteners are tightened correctly — critical in automotive, aviation, and assembly.","points":["Click, dial, and digital torque wrenches each suit different work.","Calibration drifts — verify annually or after drops.","Torque-plus-angle covers modern stretch bolts.","Under/over-torquing both cause failures."],"examples":["Head bolts torqued in sequence to spec preventing gasket failure.","Calibrating a wrench that had drifted 15% high."],"history":["Torque wrenches (1930s-40s) brought science to tightening.","Digital models added angle and data logging."],"uses":["Engine assembly.","Wheel installation safety.","Manufacturing quality."],"qa":[["Why does torque matter?","Clamp load determines joint integrity — guesswork fails."],["Can I use a torque wrench as a breaker bar?","No — it damages calibration."],["How often calibrate?","Annually, or after drops or heavy use."]]},{"title":"Wheel Alignment Tools","brief":"Alignment tools measure camber, caster, and toe — keeping tires wearing evenly and cars tracking straight.","points":["Toe misalignment eats tires fastest.","Camber affects cornering grip and inner/outer wear.","Modern systems use cameras and targets for precision.","Check alignment after suspension work or impacts."],"examples":["An alignment fixing a pull and uneven wear after a pothole.","Pre-purchase alignment check revealing accident damage."],"history":["String and bubble gauges → optical → computerized camera systems.","ADAS calibration added new complexity."],"uses":["Tire longevity.","Handling and safety.","Accident damage assessment."],"qa":[["How often align?","Annually, or after impacts and suspension work."],["Can I align at home?","String methods work for track cars; street cars deserve pro equipment."],["Why does my car pull?","Alignment, tires, or brakes — alignment check comes first."]]},{"title":"Ground Fault Testers","brief":"Ground fault and outlet testers verify wiring safety: grounds, polarity, and GFCI/AFCI function.","points":["Outlet testers catch open grounds and reversed polarity instantly.","GFCI testers verify trip function — test monthly.","Circuit analyzers measure voltage drop under load.","AFCI testers verify arc-fault protection."],"examples":["An outlet tester finding an open ground in a renovation.","Monthly GFCI tests catching a failed protector."],"history":["Simple neon testers → digital analyzers.","AFCIs (2000s) added arc-fire protection."],"uses":["Home electrical safety checks.","Renovation verification.","Rental property maintenance."],"qa":[["Are $10 testers enough?","For basic checks, yes — they catch the common faults."],["How often test GFCIs?","Monthly per manufacturers."],["What is an open ground?","A missing safety ground — shock hazard on fault."]]},{"title":"Engine Borescopes (Automotive)","brief":"Automotive borescopes inspect inside engines through spark-plug holes — valves, pistons, and cylinder walls.","points":["Check cylinder walls for scoring before buying used.","Inspect valves for carbon buildup.","Verify timing marks and chain condition.","Document with photos for records or disputes."],"examples":["Scored cylinder walls found before purchasing a used truck.","Carbon buildup assessed to justify a cleaning service."],"history":["Industrial borescopes adapted for automotive (2000s).","Affordable articulating models (2010s) made them common."],"uses":["Pre-purchase inspections.","Misfire and compression-loss diagnosis.","Verifying repair quality."],"qa":[["Can I scope through spark plug holes?","Yes — the standard access point."],["What am I looking for?","Scoring, carbon, valve condition, foreign objects."],["Worth buying?","Absolutely for used-car buyers — it pays for itself once."]]},{"title":"Water Quality Test Kits (Advanced)","brief":"Beyond basic pH: comprehensive kits test hardness, iron, chlorine, bacteria, and contaminants.","points":["Hardness affects plumbing and appliances.","Iron and manganese stain and taste.","Bacteria tests (coliform) are the critical safety check.","Lab tests for lead, arsenic, and PFAS where relevant."],"examples":["Hardness testing sizing a water softener correctly.","Bacteria test prompting well shock chlorination."],"history":["Hach and LaMotte professionalized field testing.","Home kits (2000s+) made screening accessible."],"uses":["Well water safety.","Treatment system sizing.","Aquarium and pool care."],"qa":[["Strips or lab?","Strips screen; labs decide — especially for health contaminants."],["How often test well water?","Annually for bacteria/nitrates; less often for full panels."],["What is hardness?","Calcium/magnesium content — affects scale and soap."]]},{"title":"Thermal Anemometers (Airflow)","brief":"Anemometers measure airflow — HVAC diagnostics, ventilation verification, and energy audits.","points":["Measure supply/return airflow to balance systems.","Verify exhaust fans actually exhaust.","Low airflow explains hot/cold rooms.","Hood and vane types suit different measurements."],"examples":["Balancing a system with a starved bedroom.","Verifying a bath fan meets code airflow."],"history":["Rotating vane (classic); hot-wire and ultrasonic followed.","HVAC commissioning made them standard."],"uses":["HVAC troubleshooting.","Ventilation verification.","Energy audits."],"qa":[["Why is one room always hot?","Often airflow — measure before guessing."],["What CFM do I need?","Varies by room and code — bath fans typically 50-110 CFM."],["Phone apps?","Not accurate — dedicated meters only."]]},{"title":"Diagnostic Software Suites","brief":"Software ties tools together: data logging, guided diagnostics, and reporting.","points":["Guided fault trees walk technicians through tests.","Data logging captures intermittents over time.","Reporting documents findings for customers.","Updates keep coverage current with new models."],"examples":["A guided routine isolating a network fault step by step.","Logged data catching an overnight voltage sag."],"history":["Paper manuals → PC software (1990s) → cloud-connected suites.","AI-assisted diagnostics are emerging."],"uses":["Professional shops.","Fleet maintenance.","Complex system troubleshooting."],"qa":[["Software or experience?","Both — software guides, experience judges."],["Is subscription software worth it?","For pros, the coverage updates pay for themselves."],["Can software replace tools?","No — it directs tool use; measurements still need instruments."]]}];
function buildContent(t,angle){
  var title=t.title,brief=t.brief,pts=t.points,exs=t.examples,his=t.history,uses=t.uses,qa=t.qa;
  var summary,sections,key_facts,i,rest;
  if(angle==='overview'){
    summary=brief+' This overview covers the essentials of '+title+': what it is, why it matters, and where it is used.';
    sections=[{heading:'What it is',body:brief+' '+pts.slice(0,2).join(' ')},{heading:'Key points',body:pts.join(' ')},{heading:'Why it matters',body:uses.slice(0,2).join(' ')}];
    key_facts=pts;
  }else if(angle==='detailed'){
    rest=pts.slice(2);
    summary='A detailed examination of '+title+'. '+brief;
    sections=[{heading:'Core details',body:pts.slice(0,3).join(' ')},{heading:'Going deeper',body:rest.length?rest.join(' '):pts.join(' ')},{heading:'Background and context',body:his.slice(0,2).join(' ')},{heading:'Where it is used',body:uses.join(' ')}];
    key_facts=pts;
  }else if(angle==='examples'){
    summary='Illustrative examples of '+title+' in practice. '+brief;
    sections=[];for(i=0;i<exs.length;i++)sections.push({heading:'Example '+(i+1),body:exs[i]});
    key_facts=pts.slice(0,3);
  }else if(angle==='faq'){
    summary='Frequently asked questions about '+title+'. '+brief;
    sections=[];for(i=0;i<qa.length;i++)sections.push({heading:'Q: '+qa[i][0],body:'A: '+qa[i][1]});
    key_facts=pts.slice(0,3);
  }else if(angle==='history'){
    summary='The background and development of '+title+'. '+brief;
    sections=[];for(i=0;i<his.length;i++)sections.push({heading:'Milestone '+(i+1),body:his[i]});
    key_facts=pts.slice(0,3);
  }else{
    summary='Practical applications of '+title+'. '+brief;
    sections=[];for(i=0;i<uses.length;i++)sections.push({heading:'Application '+(i+1),body:uses[i]});
    key_facts=pts.slice(0,3);
  }
  return{summary:summary,sections:sections,key_facts:key_facts};
}
function defaultDemo(){
  return{kind:'record-program',
    program:"// record card — run with: node demo.js\n// (place the record JSON next to this file as record.json)\nconst card = JSON.parse(require('fs').readFileSync('record.json', 'utf8'));\nconsole.log(card.id + ' — ' + card.title + ' [' + card.src + ']');",
    note:'A runnable program card for this record. Save as demo.js, save the record JSON as record.json beside it, and run with node.'};
}
function generate(seed,opts){
  opts=opts||{};
  var s=(seed>>>0)||1;
  var ti=(((s-1)/6)|0)%TOPICS.length, ai=(s-1)%6;
  var angle=ANGLES[ai];
  if(opts.genre&&ANGLES.indexOf(opts.genre)>=0)angle=opts.genre;
  var t=TOPICS[ti],title=t.title,brief=t.brief,topic=t;
  var ctopic=opts.topic?String(opts.topic).trim().slice(0,120):'';
  if(ctopic){title=ctopic;brief='A user-requested '+RECORD_KIND+' on "'+ctopic+'".';
    topic={title:title,brief:brief,points:t.points,examples:t.examples,history:t.history,uses:t.uses,qa:t.qa,demo:t.demo};}
  var id=PREFIX+pad(s);
  var content=buildContent(topic,angle);
  var demo=topic.demo||defaultDemo();
  return{id:id,title:title+' ('+angle+')',description:brief+' This '+angle+' guide provides comprehensive coverage.',genre:angle,type:RECORD_KIND,content:content,demo:demo,src:SRC,_seed:s};
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return{ok:false,errors:['not an object']};
  if(typeof r.id!=='string'||r.id.indexOf(PREFIX)!==0||!/\d{6}$/.test(r.id))e.push('id');
  if(typeof r.title!=='string'||r.title.length<8)e.push('title');
  if(typeof r.description!=='string'||r.description.length<40)e.push('description');
  if(ANGLES.indexOf(r.genre)<0)e.push('genre');
  if(!r.content||typeof r.content!=='object'||typeof r.content.summary!=='string'||r.content.summary.length<40)e.push('content');
  if(!r.demo||typeof r.demo!=='object')e.push('demo');
  return{ok:!e.length,errors:e};
}
function driftCheck(rec,sample){
  for(var i=0;i<sample.length;i++){if(sample[i]&&sample[i].t===rec.title)return{ok:false,errors:['duplicate title in archive sample']};}
  return{ok:true,errors:[]};
}
var gen={version:'jahdb-diagnostic-tools-generator-1.0',generate:generate,validate:validate,driftCheck:driftCheck,genres:ANGLES};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('diagnostic-tools',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();